sed 's/\([^\\]\)%.*/\1/; s/^%.*//' $f | awk '{
  for(e in x) {}
}
/\\begin\{(definition|lemma|theorem|proof)\}/{
  match($0,/\\begin\{[a-z]+\}/); env=substr($0,RSTART+7,RLENGTH-8); d[env]++
}
/\\end\{(definition|lemma|theorem|proof)\}/{
  match($0,/\\end\{[a-z]+\}/); env=substr($0,RSTART+5,RLENGTH-6); d[env]--
}
END{for(e in d) print e": "d[e]}'

